/// <summary>
/// PaffH 13.12.24
/// </summary>
/// <param name = "append">boolean</param>
public void create(boolean append)
{
    next create(append);
    this.nDX_enableButtonProdIdent();
}

/// <summary>
/// PaffH 13.12.24
/// last modified: PaffH 18.12.24
/// </summary>
/// <returns>int</returns>
int active()
{
    ProdParmStartUp prodParmStartUp = this.cursor();
    prodParmStartUp.NDXPrintProdProdIdent = NDXProdTableProdIdentProdPool::checkPrintProdIdentQRCodesForProdPool(prodParmStartUp);
    prodParmStartUp.update();

    int ret = next active();

    this.nDX_enableButtonProdIdent();

    return ret;
}

/// <summary>
/// PaffH 13.12.24
/// </summary>
public void nDX_enableButtonProdIdent()
{
    ProdParmStartUp prodParmStartUp = this.cursor();
    FormRun formRun = this.formRun();
    FormControl nDXSetupButtonProdIdentCtrl = formRun.design().controlName(formControlStr(ProdParmStartUp, NDXSetupButtonProdProdIdent));

    if (nDXSetupButtonProdIdentCtrl)
    {
        nDXSetupButtonProdIdentCtrl.enabled(prodParmStartUp.NDXPrintProdProdIdent == NoYes::Yes);
    }
}
